-- Fresh r2 only, before the predictive namespace DDL witnesses are armed.
SET ROLE __OWNER__;
CREATE TABLE predictive_jobs_v4.legacy_adoptions(
 control uuid PRIMARY KEY,ordinal bigint GENERATED ALWAYS AS IDENTITY UNIQUE,job_id uuid NOT NULL REFERENCES predictive_jobs_v4.jobs(id),
 tenant text NOT NULL,actor text NOT NULL,command uuid NOT NULL,native_hash text NOT NULL CHECK(native_hash~'^[a-f0-9]{64}$'),
 plan_digest text NOT NULL CHECK(plan_digest~'^[a-f0-9]{64}$'),native_grant bigint NOT NULL CHECK(native_grant>0),native_status text NOT NULL,
 migration uuid NOT NULL,external_possible boolean NOT NULL,recover_closed boolean NOT NULL,queue_grant bigint NOT NULL CHECK(queue_grant>0),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE FUNCTION predictive_jobs_v4._legacy_adoption_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP<>'INSERT' OR NOT EXISTS(SELECT 1 FROM predictive_jobs_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current()) THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_IMMUTABLE';END IF;RETURN NEW;END $$;
CREATE TRIGGER predictive_adoption_write BEFORE INSERT OR UPDATE OR DELETE ON predictive_jobs_v4.legacy_adoptions FOR EACH ROW EXECUTE FUNCTION predictive_jobs_v4._legacy_adoption_guard();
CREATE TRIGGER predictive_adoption_truncate BEFORE TRUNCATE ON predictive_jobs_v4.legacy_adoptions FOR EACH STATEMENT EXECUTE FUNCTION predictive_jobs_v4._legacy_adoption_guard();
ALTER TABLE predictive_jobs_v4.legacy_adoptions ENABLE ALWAYS TRIGGER predictive_adoption_write;
ALTER TABLE predictive_jobs_v4.legacy_adoptions ENABLE ALWAYS TRIGGER predictive_adoption_truncate;
REVOKE ALL ON TABLE predictive_jobs_v4.legacy_adoptions FROM PUBLIC;
REVOKE ALL ON FUNCTION predictive_jobs_v4._legacy_adoption_guard() FROM PUBLIC;
CREATE FUNCTION predictive_jobs_v4.read_adoption_v4(tenant text,actor text,control uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,predictive_jobs_v4,pg_temp AS $$
DECLARE a predictive_jobs_v4.legacy_adoptions;j predictive_jobs_v4.jobs;BEGIN PERFORM predictive_jobs_v4._assert(tenant,false);SELECT * INTO a FROM predictive_jobs_v4.legacy_adoptions q WHERE q.control=read_adoption_v4.control AND q.tenant=read_adoption_v4.tenant AND q.actor=read_adoption_v4.actor;IF NOT FOUND THEN RETURN NULL;END IF;SELECT * INTO STRICT j FROM predictive_jobs_v4.jobs WHERE id=a.job_id;RETURN jsonb_build_object('controlId',a.control,'nativeHash',a.native_hash,'recoverClosedAcceptance',a.recover_closed,'commandId',a.command,'superseded',a.ordinal<>(SELECT max(q.ordinal) FROM predictive_jobs_v4.legacy_adoptions q WHERE q.job_id=a.job_id),'job',predictive_jobs_v4._public(j));END $$;
CREATE FUNCTION predictive_jobs_v4.enqueue_adoption_v4(tenant text,actor text,wanted uuid,command uuid,action text,request text,sealed_command jsonb,sealed_grant jsonb,until_time timestamptz,control uuid,expected_sql_grant bigint,expected jsonb,recover_closed boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,predictive_jobs_v4,pg_temp AS $$
DECLARE a predictive_jobs_v4.legacy_adoptions;j predictive_jobs_v4.jobs;BEGIN
 PERFORM predictive_jobs_v4._assert(tenant,false);
 IF control IS NULL OR expected_sql_grant IS NULL OR expected_sql_grant<0 OR recover_closed IS NULL OR expected IS NULL OR jsonb_typeof(expected)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(expected))<>6 OR coalesce(expected->>'nativeHash','')!~'^[a-f0-9]{64}$' OR coalesce(expected->>'planDigest','')!~'^[a-f0-9]{64}$' OR coalesce(expected->>'nativeGrantRevision','')!~'^[1-9][0-9]*$' OR coalesce(expected->>'nativeStatus','') NOT IN('PENDING','WAITING_AUTH','HUMAN_REVIEW','COMMITTED','CANCELLED') OR jsonb_typeof(expected->'externalPossible') IS DISTINCT FROM 'boolean' OR coalesce(expected->>'migrationId','')!~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_INPUT';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('predictive-adoption:'||tenant||':'||control::text,0));PERFORM pg_advisory_xact_lock(hashtextextended('console:'||predictive_jobs_v4._business_key(tenant,actor,command),0));
 SELECT * INTO a FROM predictive_jobs_v4.legacy_adoptions q WHERE q.control=enqueue_adoption_v4.control;
 IF FOUND THEN IF a.tenant IS DISTINCT FROM tenant OR a.actor IS DISTINCT FROM actor OR a.command IS DISTINCT FROM command OR a.native_hash IS DISTINCT FROM expected->>'nativeHash' OR a.plan_digest IS DISTINCT FROM expected->>'planDigest' OR a.native_grant IS DISTINCT FROM (expected->>'nativeGrantRevision')::bigint OR a.native_status IS DISTINCT FROM expected->>'nativeStatus' OR a.migration IS DISTINCT FROM (expected->>'migrationId')::uuid OR a.external_possible IS DISTINCT FROM (expected->>'externalPossible')::boolean OR a.recover_closed IS DISTINCT FROM recover_closed THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_CONFLICT';END IF;SELECT * INTO STRICT j FROM predictive_jobs_v4.jobs WHERE id=a.job_id;RETURN predictive_jobs_v4._public(j);END IF;
 IF NOT recover_closed AND EXISTS(SELECT 1 FROM predictive_jobs_v4.command_fences f WHERE f.tenant=enqueue_adoption_v4.tenant AND f.actor_id=actor AND f.command_id=command) THEN RAISE EXCEPTION 'PREDICTIVE_COMMAND_ACCEPTANCE_CLOSED';END IF;
 SELECT * INTO j FROM predictive_jobs_v4.jobs q WHERE q.tenant=enqueue_adoption_v4.tenant AND q.actor_id=actor AND q.command_id=command FOR UPDATE;
 IF NOT FOUND THEN
  IF expected_sql_grant<>0 THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_GRANT_CONFLICT';END IF;
  IF NOT recover_closed AND EXISTS(SELECT 1 FROM predictive_jobs_v4.command_fences f WHERE f.tenant=enqueue_adoption_v4.tenant AND f.actor_id=actor AND f.command_id=command) THEN RAISE EXCEPTION 'PREDICTIVE_COMMAND_ACCEPTANCE_CLOSED';END IF;
  PERFORM predictive_jobs_v4.enqueue_v4(tenant,actor,wanted,command,action,request,sealed_command,sealed_grant,until_time);
  SELECT * INTO STRICT j FROM predictive_jobs_v4.jobs WHERE id=wanted FOR UPDATE;
 ELSE
  IF j.id IS DISTINCT FROM wanted OR j.request_hash IS DISTINCT FROM request OR j.action IS DISTINCT FROM action OR j.grant_revision<>expected_sql_grant OR j.retry_grant IS NOT NULL OR j.status IN('COMMITTED','FAILED','CANCELLED') OR sealed_grant IS NULL OR until_time IS NULL OR until_time<=clock_timestamp() THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_GRANT_CONFLICT';END IF;
  INSERT INTO predictive_jobs_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE predictive_jobs_v4.jobs SET sealed_grant=enqueue_adoption_v4.sealed_grant,grant_revision=j.grant_revision+1,grant_until=until_time,status='ACCEPTED',cancel_requested=false,worker_id=NULL,claim_token=NULL,lease_until=NULL,auth_deadline=NULL,fence=fence+1,next_attempt=clock_timestamp(),updated_at=clock_timestamp() WHERE id=j.id RETURNING * INTO j;DELETE FROM predictive_jobs_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current();
 END IF;
 INSERT INTO predictive_jobs_v4._ctx VALUES(pg_backend_pid(),txid_current());
 UPDATE predictive_jobs_v4.jobs SET external_started=external_started OR (expected->>'externalPossible')::boolean WHERE id=j.id RETURNING * INTO j;
 INSERT INTO predictive_jobs_v4.legacy_adoptions(control,job_id,tenant,actor,command,native_hash,plan_digest,native_grant,native_status,migration,external_possible,recover_closed,queue_grant) VALUES(control,j.id,tenant,actor,command,expected->>'nativeHash',expected->>'planDigest',(expected->>'nativeGrantRevision')::bigint,expected->>'nativeStatus',(expected->>'migrationId')::uuid,(expected->>'externalPossible')::boolean,recover_closed,j.grant_revision);
 DELETE FROM predictive_jobs_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current();RETURN predictive_jobs_v4._public(j);
END $$;
CREATE FUNCTION predictive_jobs_v4.claim_adoption_v4(tenant text,wanted uuid,owner uuid,token uuid,fence bigint,grant_revision bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,predictive_jobs_v4,pg_temp AS $$
DECLARE j predictive_jobs_v4.jobs;a predictive_jobs_v4.legacy_adoptions;BEGIN j:=predictive_jobs_v4._claim(tenant,wanted,owner,token,fence,grant_revision);SELECT * INTO a FROM predictive_jobs_v4.legacy_adoptions q WHERE q.job_id=j.id ORDER BY q.ordinal DESC LIMIT 1;IF NOT FOUND THEN RETURN NULL;END IF;RETURN jsonb_build_object('controlId',a.control,'nativeHash',a.native_hash,'planDigest',a.plan_digest,'nativeGrantRevision',a.native_grant::text,'nativeStatus',a.native_status,'migrationId',a.migration,'externalPossible',a.external_possible,'queueGrantRevision',a.queue_grant::text);END $$;
CREATE FUNCTION predictive_jobs_v4.prepare_adoption_v4(tenant text,wanted uuid,owner uuid,token uuid,fence bigint,grant_revision bigint,deadline timestamptz,control uuid,command uuid,revision bigint,root bytea,operations jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,predictive_jobs_v4,state_map_v1,pg_temp AS $$
DECLARE j predictive_jobs_v4.jobs;a predictive_jobs_v4.legacy_adoptions;before_job jsonb;before_state jsonb;b jsonb;rec jsonb;m jsonb;checkpoint jsonb;host jsonb;receipt jsonb;event jsonb;ord jsonb;tip jsonb;r jsonb;cancel_receipt jsonb;cancel_audit jsonb;cancel_order jsonb;
BEGIN
 PERFORM state_map_v1.read_head_v1(tenant);PERFORM predictive_jobs_v4.lock_v4(tenant,wanted,owner,token,fence,grant_revision,deadline);j:=predictive_jobs_v4._claim(tenant,wanted,owner,token,fence,grant_revision);
 SELECT * INTO STRICT a FROM predictive_jobs_v4.legacy_adoptions q WHERE q.control=prepare_adoption_v4.control AND q.job_id=j.id;
 IF a.ordinal<>(SELECT max(q.ordinal) FROM predictive_jobs_v4.legacy_adoptions q WHERE q.job_id=j.id) OR a.queue_grant>j.grant_revision THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_SUPERSEDED';END IF;
 before_job:=predictive_jobs_v4._sdk(j);before_state:=predictive_jobs_v4._state(tenant,'predictive_job',j.business_key);rec:=predictive_jobs_v4._state(tenant,'predictive_reconciliation',j.business_key)->'value';m:=predictive_jobs_v4._state(tenant,'receipt','predictive_read_migration:'||a.migration::text)->'value';checkpoint:=predictive_jobs_v4._state(tenant,'predictive_read_migration',a.migration::text)->'value';
 IF before_state->>'hash' IS DISTINCT FROM a.native_hash OR before_job->>'planDigest' IS DISTINCT FROM a.plan_digest OR before_job->>'grantRevision' IS DISTINCT FROM a.native_grant::text OR before_job->>'status' IS DISTINCT FROM a.native_status OR rec->>'authority' IS DISTINCT FROM 'NONE' OR rec->>'tenantId' IS DISTINCT FROM tenant OR rec->>'actorId' IS DISTINCT FROM j.actor_id OR rec->>'commandId' IS DISTINCT FROM j.command_id::text OR rec->>'requestHash' IS DISTINCT FROM j.request_hash OR rec->>'planDigest' IS DISTINCT FROM a.plan_digest OR rec->>'operationId' IS DISTINCT FROM a.migration::text OR rec->>'externalCreationMayHaveStarted' IS DISTINCT FROM a.external_possible::text OR checkpoint->>'phase' IS DISTINCT FROM 'COMMITTED' OR checkpoint->>'operationId' IS DISTINCT FROM a.migration::text OR m->>'operationId' IS DISTINCT FROM a.migration::text OR m->>'tenantId' IS DISTINCT FROM tenant OR m->>'configuration' IS DISTINCT FROM predictive_jobs_v4._state(tenant,'domain_head','predictive')->'value'->>'configuration' THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_STALE';END IF;
 IF predictive_jobs_v4._state(tenant,'domain_head','control')->'value'->>'status' IS DISTINCT FROM 'ACTIVE' THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_FENCED';END IF;
 host:=predictive_jobs_v4._state(tenant,'predictive_host',j.business_key)->'value';IF host IS NOT NULL AND host<>'null'::jsonb THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_HOST_EXISTS';END IF;
 IF a.external_possible AND NOT j.external_started OR a.external_possible AND before_job->>'status'='CANCELLED' THEN RAISE EXCEPTION 'PREDICTIVE_CREATION_RECOVERY_REQUIRED';END IF;
 IF jsonb_typeof(operations) IS DISTINCT FROM 'array' OR jsonb_array_length(operations) NOT BETWEEN 5 AND 7 OR EXISTS(SELECT 1 FROM jsonb_array_elements(operations) o WHERE ((o->>'namespace'='predictive_host' AND o->>'key'=j.business_key) OR (o->>'namespace'='predictive_job' AND o->>'key'=j.business_key) OR (o->>'namespace'='receipt' AND o->>'key'='predictive_adoption:'||a.control::text) OR o->>'namespace' IN('audit','audit_order') OR (o->>'namespace'='domain_head' AND o->>'key'='audit')) IS NOT TRUE) THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_OPERATIONS';END IF;
 IF jsonb_array_length(operations)<>(CASE WHEN before_job->>'status' IN('COMMITTED','CANCELLED') THEN 5 ELSE 6 END) OR (SELECT count(*) FROM jsonb_array_elements(operations) o WHERE o->>'namespace'='audit')<>1 OR (SELECT count(*) FROM jsonb_array_elements(operations) o WHERE o->>'namespace'='audit_order')<>1 OR (SELECT count(*) FROM jsonb_array_elements(operations) o WHERE o->>'namespace'='predictive_host')<>1 OR (SELECT count(*) FROM jsonb_array_elements(operations) o WHERE o->>'namespace'='receipt')<>1 OR (SELECT count(*) FROM jsonb_array_elements(operations) o WHERE o->>'namespace'='domain_head')<>1 THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_OPERATIONS';END IF;
 tip:=predictive_jobs_v4._state(tenant,'domain_head','audit')->'value';r:=state_map_v1.apply_delta_v1(tenant,command,revision,root,operations);PERFORM predictive_jobs_v4.lock_v4(tenant,wanted,owner,token,fence,grant_revision,deadline);b:=predictive_jobs_v4._sdk(j);
 IF before_job->>'status' IN('COMMITTED','CANCELLED') THEN IF b IS DISTINCT FROM before_job THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_TERMINAL_CHANGED';END IF;
 ELSIF (b-ARRAY['status','grantRevision','lastError','nextAttempt','updatedAt']) IS DISTINCT FROM (before_job-ARRAY['status','grantRevision','lastError','nextAttempt','updatedAt']) OR b->>'grantRevision' IS DISTINCT FROM (a.native_grant+1)::text OR b->>'status' IS DISTINCT FROM (CASE WHEN a.native_status='HUMAN_REVIEW' THEN 'HUMAN_REVIEW' ELSE 'PENDING' END) OR b->>'nextAttempt' IS DISTINCT FROM '0' OR a.native_status='HUMAN_REVIEW' AND b->'lastError' IS DISTINCT FROM before_job->'lastError' THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_JOB_CHANGED';END IF;
 host:=predictive_jobs_v4._state(tenant,'predictive_host',j.business_key)->'value';receipt:=predictive_jobs_v4._state(tenant,'receipt','predictive_adoption:'||a.control::text)->'value';
 IF host->>'format' IS DISTINCT FROM 'IDMS_PREDICTIVE_HOST_V4_1' OR host->>'tenantId' IS DISTINCT FROM tenant OR host->>'jobId' IS DISTINCT FROM j.id::text OR host->>'actorId' IS DISTINCT FROM j.actor_id OR host->>'commandId' IS DISTINCT FROM j.command_id::text OR host->>'requestHash' IS DISTINCT FROM j.request_hash OR host->>'grantRevision' IS DISTINCT FROM j.grant_revision::text OR receipt->>'format' IS DISTINCT FROM 'IDMS_PREDICTIVE_LEGACY_ADOPTION_V4_1' OR receipt->>'tenantId' IS DISTINCT FROM tenant OR receipt->>'controlId' IS DISTINCT FROM a.control::text OR receipt->>'jobId' IS DISTINCT FROM j.id::text OR receipt->>'jobKey' IS DISTINCT FROM j.business_key OR receipt->>'actorId' IS DISTINCT FROM j.actor_id OR receipt->>'commandId' IS DISTINCT FROM j.command_id::text OR receipt->>'requestHash' IS DISTINCT FROM j.request_hash OR receipt->>'planDigest' IS DISTINCT FROM a.plan_digest OR receipt->>'beforeNativeHash' IS DISTINCT FROM a.native_hash OR receipt->>'migrationId' IS DISTINCT FROM a.migration::text OR receipt->>'sdkRevision' IS DISTINCT FROM b->>'grantRevision' OR receipt->>'sqlGrantRevision' IS DISTINCT FROM j.grant_revision::text THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_HOST_RECEIPT';END IF;
 event:=predictive_jobs_v4._state(tenant,'audit',receipt->>'auditEventId')->'value';ord:=predictive_jobs_v4._state(tenant,'audit_order',lpad(receipt->>'auditPosition',20,'0'))->'value';
 IF event->>'tenantId' IS DISTINCT FROM tenant OR event->>'actorType' IS DISTINCT FROM 'USER' OR event->>'actorId' IS DISTINCT FROM j.actor_id OR event->>'action' IS DISTINCT FROM 'PREDICTIVE_LEGACY_JOB_ADOPTED' OR event->>'previousHash' IS DISTINCT FROM tip->>'hash' OR event->>'hash' IS DISTINCT FROM receipt->>'auditHash' OR event->>'eventId' IS DISTINCT FROM ord->>'eventId' OR ord->>'tenantId' IS DISTINCT FROM tenant OR receipt->>'auditPosition' IS DISTINCT FROM ((tip->>'count')::bigint+1)::text OR event->'metadata'->>'adoptionId' IS DISTINCT FROM a.control::text OR event->'metadata'->>'jobKey' IS DISTINCT FROM j.business_key OR event->'metadata'->>'planDigest' IS DISTINCT FROM a.plan_digest OR event->'metadata'->>'originalActor' IS DISTINCT FROM j.actor_id OR predictive_jobs_v4._state(tenant,'domain_head','audit')->'value'->>'hash' IS DISTINCT FROM event->>'hash' THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_AUDIT';END IF;
 IF b->>'status'='COMMITTED' THEN PERFORM predictive_jobs_v4.finish_v4(tenant,wanted,owner,token,fence,grant_revision);
 ELSIF b->>'status'='HUMAN_REVIEW' THEN PERFORM predictive_jobs_v4.settle_v4(tenant,wanted,owner,token,fence,grant_revision);
 ELSIF b->>'status'='CANCELLED' THEN
  cancel_receipt:=predictive_jobs_v4._state(tenant,'receipt','predictive_cancel:'||j.business_key)->'value';cancel_audit:=predictive_jobs_v4._state(tenant,'audit',cancel_receipt->>'auditEventId')->'value';cancel_order:=predictive_jobs_v4._state(tenant,'audit_order',lpad(cancel_receipt->>'auditPosition',20,'0'))->'value';
  IF j.external_started OR cancel_receipt->>'key' IS DISTINCT FROM j.business_key OR cancel_receipt->>'requestHash' IS DISTINCT FROM j.request_hash OR cancel_receipt->>'planDigest' IS DISTINCT FROM a.plan_digest OR cancel_audit->>'actorId' IS DISTINCT FROM j.actor_id OR cancel_audit->>'action' IS DISTINCT FROM 'PREDICTIVE_COMMAND_CANCELLED' OR cancel_audit->>'hash' IS DISTINCT FROM cancel_receipt->>'auditHash' OR cancel_order->>'eventId' IS DISTINCT FROM cancel_audit->>'eventId' THEN RAISE EXCEPTION 'PREDICTIVE_ADOPTION_CANCEL_UNPROVEN';END IF;
  INSERT INTO predictive_jobs_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE predictive_jobs_v4.jobs SET status='CANCELLED',cancel_requested=true,result=NULL,error_code='CANCELLED',worker_id=NULL,claim_token=NULL,lease_until=NULL,auth_deadline=NULL,updated_at=clock_timestamp() WHERE id=j.id;DELETE FROM predictive_jobs_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current();
 END IF;RETURN r;
END $$;
REVOKE ALL ON FUNCTION predictive_jobs_v4.read_adoption_v4(text,text,uuid),predictive_jobs_v4.enqueue_adoption_v4(text,text,uuid,uuid,text,text,jsonb,jsonb,timestamptz,uuid,bigint,jsonb,boolean),predictive_jobs_v4.claim_adoption_v4(text,uuid,uuid,uuid,bigint,bigint),predictive_jobs_v4.prepare_adoption_v4(text,uuid,uuid,uuid,bigint,bigint,timestamptz,uuid,uuid,bigint,bytea,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION predictive_jobs_v4.read_adoption_v4(text,text,uuid),predictive_jobs_v4.enqueue_adoption_v4(text,text,uuid,uuid,text,text,jsonb,jsonb,timestamptz,uuid,bigint,jsonb,boolean) TO __INGRESS__,__WORKER__;
GRANT EXECUTE ON FUNCTION predictive_jobs_v4.claim_adoption_v4(text,uuid,uuid,uuid,bigint,bigint),predictive_jobs_v4.prepare_adoption_v4(text,uuid,uuid,uuid,bigint,bigint,timestamptz,uuid,uuid,bigint,bytea,jsonb) TO __WORKER__;
RESET ROLE;
